INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83790, 'spa', 'Oscuridad, tiniebla', 'Oscuridad densa e impenetrable, empleada en poesía sapiencial para expresar temor, ocultamiento o calamidad. En Job 3:6 la tiniebla ''se apodera'' de la noche maldita; en Job 10:22 describe el Seol como tierra de lobreguez; en Job 28:3 los mineros penetran la piedra de oscuridad; y en Salmo 91:6 denota el terror que acecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83796, 'spa', 'Oscuridad densa literal — la ausencia de luz en su forma más intensa', 'Oscuridad densa literal — la ausencia de luz en su forma más intensa. Abarca la oscuridad sobrenatural de la plaga sobre Egipto, donde Éxodo 10:22 la empareja con חֹשֶׁךְ, el crepúsculo ominoso de Proverbios 7:9 descrito junto a «la pupila de la noche», y los pasajes escatológicos del Día de YHWH (Joel 2:2; Sof 1:15) donde se acumula con nube, densa nube y negrura. Denota una oscuridad casi tangible que devora toda luz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83797, 'spa', 'Oscuridad figurada que representa calamidad, juicio divino o ruina espiritual', 'Oscuridad figurada que representa calamidad, juicio divino o ruina espiritual. Deuteronomio 28:29 la emplea como imagen de maldición del pacto: andar a tientas en tinieblas al mediodía. Jeremías 23:12 sitúa a los falsos profetas en un camino resbaladizo hacia la oscuridad. Isaías 58:10 y 59:9 la contrastan con la luz del mediodía, mostrando que la oscuridad moral es tan palpable como la noche física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83806, 'spa', 'Cesar o agotarse', 'Llegar a su fin, cesar o quedar exhausto. El verbo describe el agotamiento total o la terminación de algo: dinero que se acaba (Gn 47:15-16), un opresor que perece (Is 16:4; 29:20, en paralelo con כָּלָה ''consumirse'' y תָּמַם ''completarse''), o la lealtad pactual de Dios que aparentemente falla (Sal 77:8, emparejado con גָּמַר ''terminar''). La forma hebrea se restringe al Qal perfecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83807, 'spa', 'confines de (la tierra) — El sentido geográfico-poético', 'confines de (la tierra) — El sentido geográfico-poético: ''confines de la tierra'' (אַפְסֵי־אָרֶץ), los límites más remotos del mundo habitado. Concentrada en Salmos, Isaías y Deuteronomio, esta frase lleva un enorme peso teológico: la soberanía de Dios se extiende hasta los confines de la tierra (Sal 2:8; Zac 9:10). La cadena constructa con אֶרֶץ es casi formulaica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83808, 'spa', 'sin embargo, pero, solo — Partícula adversativa-restrictiva', 'sin embargo, pero, solo — Partícula adversativa-restrictiva: ''sin embargo, pero, excepto, solo''. El sustantivo de cesación se ha gramaticalizado como marcador discursivo que introduce restricciones. En Nm 13:28 los espías conceden la bondad de la tierra pero — ''sin embargo, el pueblo es fuerte''; en Jue 4:9 Débora accede a acompañar a Barac, pero — ''solo que la gloria no será tuya''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83809, 'spa', 'no hay nadie, ninguno — Negación predicativa', 'no hay nadie, ninguno — Negación predicativa: ''no hay nadie, no queda ninguno''. Se usa para negar la existencia o supervivencia de personas o cosas, frecuentemente en contextos de juicio o devastación. Dt 32:36 anuncia que Dios actuará cuando vea que ''no queda nadie''; 2 R 14:26 usa אֶפֶס dos veces para describir la total indefensión de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83813, 'spa', 'nada, nulidad — Nada sustantiva', 'nada, nulidad — Nada sustantiva: cero absoluto o total insignificancia, concentrada en la polémica del Segundo Isaías contra la idolatría y las naciones. Is 40:17 declara que las naciones son ''como nada y como inexistencia'' (כְּאַיִן וּכְאֶפֶס); Is 41:29 dice de los ídolos ''todos ellos son אֶפֶס''. Este sentido está estrechamente relacionado con el sentido 2, pero enfatiza la vacuidad ontológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83816, 'spa', 'sin, por falta de — Uso preposicional privativo (frecuentemente בְּאֶפֶס)', 'sin, por falta de — Uso preposicional privativo (frecuentemente בְּאֶפֶס): ''sin, por falta de''. Indica privación o ausencia de algo esperado. Pr 14:28 advierte que ''sin pueblo, el príncipe se arruina''; Pr 26:20 señala que ''sin chismoso, la contienda cesa''. La construcción בְּ + אֶפֶס crea una frase privativa compacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83841, 'spa', 'Víbora venenosa', 'Job 20:16 advierte que el impío «chupará veneno de víboras; la lengua de la víbora lo matará»: la riqueza obtenida por maldad se convierte en ponzoña interior. Isaías 30:6 incluye «la víbora y la serpiente voladora» entre los peligros del desierto. Isaías 59:5 acusa a los malvados de incubar «huevos de víbora»: quien los come, muere; al aplastarlos, brotan más serpientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83842, 'spa', 'Rodear o engullir', 'Envolver o engullir, describiendo la experiencia aterradora de ser rodeado por fuerzas letales desde todos los flancos. El uso literal en Jonás 2:5 retrata las aguas cerrándose sobre la cabeza del profeta, mientras que en 2 S 22:5, Sal 18:4 y Sal 116:3 los «torrentes de muerte» y «cuerdas del Seol» envuelven al hablante. En el Sal 40:12 son los males (רָעוֹת) los que lo cercan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83843, 'spa', 'Contenerse, dominarse', 'Obligarse a uno mismo a contener emociones o impulsos intensos mediante un esfuerzo deliberado. La conjugación reflexiva Hitpael subraya la lucha interna del sujeto contra sus propios sentimientos. El español ''contenerse'' y ''se contuvo'' capturan con precisión esta contención reflexiva. Los usos más memorables involucran a José forzándose a no llorar antes de revelar su identidad (Gn 43:31; 45:1), pero también a Dios mismo refrenando Su poder (Is 42:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83850, 'spa', 'Afec (topónimo)', 'El topónimo Afec (אֲפֵק / אֲפִיק), que designa varias ciudades fortificadas en Canaán. La más destacada se halla cerca de Jezreel, vinculada a las guerras arameo-israelitas (1 Re 20:26, 30; 2 Re 13:17). Un segundo Afec en la llanura filistea fue escenario de la captura del arca (1 Sam 4:1) y la concentración filistea antes de la muerte de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83858, 'spa', 'Residuo en polvo que queda tras la combustión, usado en contextos cultuales, pen', 'Residuo en polvo que queda tras la combustión, usado en contextos cultuales, penitenciales y metafóricos. En la ley ritual, las cenizas de la vaca roja sirven para la purificación (Nm 19:9-10). En la lamentación y la penitencia, la ceniza sobre la cabeza o el cuerpo señala duelo (Est 4:1; Jr 6:26; Ez 27:30) y contrición ante Dios (Dn 9:3; Jon 3:6). Figuradamente, la ceniza expresa insignificancia y carencia de valor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83866, 'spa', 'Polluelo o cría', 'Crías de aves o polluelos, los indefensos retoños que se encuentran en el nido. Dt 22:6 emplea el plural dos veces en el compasivo mandamiento de soltar a la madre y no tomarla junto con sus crías, ley que los rabinos consideraban paradigma de misericordia. Job 39:30 presenta las fieras crías del buitre alimentándose de sangre. El Sal 84:3 sitúa a la golondrina y sus polluelos junto al altar divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83868, 'spa', 'Efraín (nombre propio)', 'Nombre propio que designa al hijo menor de José bendecido por Jacob (Gn 48:13-20), la prominente tribu israelita descendiente de él y el territorio montañoso central asignado a dicha tribu. En la literatura profética, especialmente Oseas, ''Efraín'' se convierte en sinécdoque del reino del norte. La etimología (''doblemente fructífero'', de פרה) se da en Gn 41:52.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83884, 'spa', 'Nombre de lugar estrechamente asociado con o idéntico a Belén de Judá, cargado d', 'Nombre de lugar estrechamente asociado con o idéntico a Belén de Judá, cargado de profunda significación patriarcal y mesiánica. Raquel fue sepultada en el camino a Efrata (Gn 35:16, 19; 48:7). Los hombres de Booz lo invocan junto a Belén al bendecir el matrimonio de Rut (Rut 4:11). El Salmo 132:6 recuerda haber hallado el arca «en los campos de Jaar» tras oír de ella «en Efrata». Miqueas 5:2 nombra a «Belén Efrata» como origen del gobernante prometido, pasaje aplicado mesiánicamente en Mateo 2:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83891, 'spa', 'Gentilicio dual', 'Adjetivo gentilicio que identifica a una persona como efraimita (de la tribu de Efraín) o como efrateo (de Efrata/Belén en Judá). En Jue 12:5 y 1 S 1:1 designa a efraimitas tribales, y en 1 R 11:26 a Jeroboam como efraimita. Pero en Rut 1:2 (''efrateos de Belén'') y 1 S 17:12 (''efrateo de Belén de Judá'') indica origen judahita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83894, 'spa', 'dedo (de la mano) — Un dedo de la mano humana, empleado tanto en sentido literal', 'dedo (de la mano) — Un dedo de la mano humana, empleado tanto en sentido literal para el miembro físico como frecuentemente en contextos cúlticos, simbólicos y teológicos. Predomina en 29 ocurrencias: describe el dedo del sacerdote aplicando sangre sacrificial (Éx 29:12; Lv 4:6), el dedo de Dios escribiendo el Decálogo (Éx 31:18; Dt 9:10) y el gesto despectivo de señalar con el dedo (Is 58:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83897, 'spa', 'dedo del pie — Un dedo del pie, es decir, un dígito del pie y no de la mano', 'dedo del pie — Un dedo del pie, es decir, un dígito del pie y no de la mano. Este sentido raro (2 veces) aparece exclusivamente en 2 Samuel 21:20, describiendo a un gigante filisteo con seis dedos en cada mano y seis dedos en cada pie. Las traducciones al inglés cambian a ''toes'', confirmando que los traductores reconocen una distinción semántica genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83910, 'spa', 'Dedos de manos y pies', 'Daniel 5:5 describe «los dedos de una mano humana» que aparecen y escriben en la pared, una manifestación sobrenatural que aterroriza a Belsasar. Daniel 2:41-42 interpreta los pies y dedos de la estatua como un reino dividido, «en parte de hierro y en parte de barro», fuerte en algunas partes y frágil en otras. Los dedos representan la extensión final de la estatua, la etapa más vulnerable antes de que la piedra destruya el conjunto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83912, 'spa', 'Coyunturas del brazo', 'Jeremías 38:12 muestra compasión en detalle práctico: «Pon los trapos y ropas entre tus axilas y las cuerdas», usando «coyunturas del brazo» para la zona vulnerable donde la cuerda cortaría durante el rescate. Ezequiel 13:18 condena a las mujeres que «cosen bandas mágicas sobre todas las coyunturas de las manos» (probablemente codos o muñecas), instrumentos de manipulación profética falsa. La referencia arquitectónica de Ezequiel 41:8 permanece oscura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83913, 'spa', 'Apartar o reservar', 'Apartar, reservar, retirar o retener algo de una porción mayor. El hilo semántico es la separación de una parte del todo: Isaac reservando una bendición (Gn 27:36), Dios retirando parte del espíritu de Moisés para redistribuirlo a los ancianos (Nm 11:17, 25), y Qohélet negándose a privarse de placer alguno (Ec 2:10). El Nifal en Ez 42:6 extiende la idea al ámbito arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83914, 'spa', 'Proximidad espacial estática', 'Proximidad espacial estática: ''junto a, cerca de, al lado de'' alguien o algo, con o sin sufijos pronominales. A lo largo de 55 ocurrencias, abarca escenas de posicionamiento y ubicación. El español ''junto a'', el francés ''à côté de'' y el alemán ''neben'' convergen en este sentido locativo. Pasajes clave incluyen a la esposa de Potifar describiendo a José como estando junto a ella (Gn 39:15-18) y las ruedas visionarias junto a los querubines (Ez 10:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83919, 'spa', 'Movimiento separativo desde una ubicación próxima, formado con la preposición pr', 'Movimiento separativo desde una ubicación próxima, formado con la preposición prefijada מִן (dando מֵאֵצֶל). Abarca 6 ocurrencias donde el énfasis recae en la partida o el alejamiento de junto a alguien. Las traducciones lo expresan con locuciones compuestas: español ''de junto a'', alemán ''von neben''. David levantándose de junto a la piedra (1 Sam 20:41) y la gloria apartándose de junto al umbral (Ez 10:18) ilustran este sentido separativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83931, 'spa', 'Azel (nombre propio)', 'Nombre propio masculino (אָצֵל, posiblemente ''noble'') que designa a un descendiente del rey Saúl por la línea de Jonatán, presente en la genealogía benjaminita de 1 Crónicas 8:37-38 y su duplicado en 9:43-44. El texto registra que Azel engendró seis hijos cuyos nombres se enumeran. Las traducciones francesas curiosamente glosan el nombre con la preposición ''à-côté-de'' (al lado de), reflejando una confusión con el homónimo preposicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83937, 'spa', 'Atesorar y almacenar', 'Guardar, almacenar o acumular, y por extension denominativa designar a alguien sobre un deposito. El Qal describe la acumulacion de bienes o riquezas, ya sea legitimamente (2 Re 20:17 = Is 39:6, los tesoros que almacenaron los antepasados de Ezequias) o injustamente (Am 3:10, acumular violencia y saqueo en palacios fortificados). El Nifal en Isaias 23:18 imagina el comercio de Tiro ya no atesorado sino entregado a los que moran ante el Senor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83938, 'spa', 'Jefe horita de Edom', 'Nombre propio Etser (hebreo אֶצֶר), que identifica a un jefe horita descendiente de Seir en la poblacion preisraelita de Edom. Aparece en la genealogia de Seir en Genesis 36:21 como uno de los hijos horitas de Seir, con sus descendientes mencionados en 36:27 y su jefatura registrada en 36:30. El paralelo en 1 Cronicas 1:38, 42 reproduce el mismo linaje. El nombre puede significar ''tesoro'' o ''pacto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83943, 'spa', 'Nombre propio y gentilicio', 'Génesis 46:16 enumera a Areli entre los hijos de Gad que bajaron a Egipto con la familia de Jacob. Números 26:17 repite el nombre en el censo del desierto, añadiendo el gentilicio «la familia de los arelitas», indicando que los descendientes de Areli formaban un grupo familiar reconocido dentro de la tribu de Gad. La doble mención —nombre personal y designación de clan— muestra cómo los individuos se convertían en cabezas de familias con identidad propia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83944, 'spa', 'emboscada, grupo de emboscada — El uso sustantivado del participio Qal (עֹרֵב) c', 'emboscada, grupo de emboscada — El uso sustantivado del participio Qal (עֹרֵב) como nombre que designa la fuerza de emboscada, la posición de emboscada o el acto de emboscar. Josué 8 concentra la mayoría de las ocurrencias (vv. 2, 4, 7, 12, 14, 19, 21), donde se narra la elaborada estrategia de emboscada contra Hai. El español ''emboscada'' traduce este sentido nominal, distinguiéndolo del verbal ''acechar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83947, 'spa', 'acechar, estar al acecho — La acción verbal básica de ocultarse para atacar por ', 'acechar, estar al acecho — La acción verbal básica de ocultarse para atacar por sorpresa. Deuteronomio 19:11 legisla el caso de quien acecha a su prójimo, mientras Jueces 16:2 describe a los de Gaza acechando a Sansón. El Salmo 10:9 emplea la vívida comparación de un león al acecho en su guarida. Las formas del Qal imperfecto y participio dominan, con Proverbios 1:11 y 1:18 extendiendo la imagen a la tentación moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83953, 'spa', 'emboscadores (Piel intensivo) — El participio intensivo del Piel (מְאָרְבִים) qu', 'emboscadores (Piel intensivo) — El participio intensivo del Piel (מְאָרְבִים) que designa emboscadores profesionales o deliberados. Jueces 9:25 describe a hombres de Siquem que ''pusieron emboscadores'' contra Abimelec en las colinas, y 2 Crónicas 20:22 registra a Dios poniendo emboscadores contra los enemigos de Judá. El tronco Piel intensifica la naturaleza deliberada u organizada de la emboscada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83975, 'spa', 'La langosta migratoria que aparece en multitudes devastadoras', 'La langosta migratoria que aparece en multitudes devastadoras. Asociada principalmente con la plaga de Egipto (Éx 10:4-19), donde funciona como instrumento del juicio divino. Incluida entre los insectos limpios permitidos como alimento (Lv 11:22). Frecuentemente empleada en símiles para multitudes abrumadoras: las hordas madianitas son ''como langostas en número'' (Jue 6:5; 7:12). Joel 1:4 la sitúa en una secuencia de cuatro especies que representa la destrucción total de las cosechas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83986, 'spa', 'Ventana, celosía, compuerta', 'Ventana enrejada, abertura o compuerta — apertura en un muro o techo. Concretamente aparece como chimenea (Os 13:3) o abertura de palomar (Isa 60:8). Eclesiastés 12:3 la usa metafóricamente para los ojos que se debilitan. La expresión אֲרֻבּוֹת הַשָּׁמַיִם (''ventanas del cielo'') describe las compuertas cósmicas que Dios abre para el diluvio o la bendición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83994, 'spa', 'cuatro (cardinal)', 'El numeral cardinal ''cuatro'' usado de manera independiente o en constructo para contar personas, objetos, direcciones, medidas y duraciones (277 ocurrencias). Traducido uniformemente en todas las lenguas meta con formas numerales básicas: árabe أربعة, español ''cuatro'', francés ''quatre''. Empleado para los cuatro ríos del paraíso (Gn 2:10), los cuatro reyes aliados (Gn 14:9) y los cuatrocientos años de peregrinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83996, 'spa', 'catorce (numeral compuesto)', 'El numeral ''cuatro'' funcionando como componente de unidades del número compuesto catorce, siempre emparejado con la palabra hebrea para diez (עָשָׂר/עֶשְׂרֵה). Las lenguas meta a menudo emplean formas compuestas específicas — español ''catorce'', francés ''quatorze'', alemán ''vierzehn'' — distinguiéndolo del cardinal independiente. Central para el cómputo calendárico: el cordero pascual se sacrifica el día decimocuarto (Éx 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84027, 'spa', 'Cuatro (número cardinal)', 'El número cardinal cuatro (אַרְבַּע femenino, אַרְבְּעָה masculino), empleado en la Biblia hebrea para enumeración directa. En Daniel cuenta los vientos del cielo (7:2), las grandes bestias (7:3), las alas de la bestia-leopardo (7:6) y los cuatro reinos (7:17), además de los hombres en el horno (3:25). En Esdras 6:17 forma el compuesto ''cuatrocientos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84030, 'spa', 'cuarenta', 'El numeral cardinal cuarenta, sustantivo indeclinable casi siempre en constructo con שָׁנָה (''año'') o יוֹם (''día'') para marcar períodos de significado divino. Denota una generación (Jue 3:11), un lapso de prueba (los años en el desierto, Nm 14:33; Moisés en el Sinaí, Éx 24:18) o una ventana de juicio (Jon 3:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84038, 'spa', 'Entrelazar hilos en un telar para producir tela o tejido, abarcando tanto la acc', 'Entrelazar hilos en un telar para producir tela o tejido, abarcando tanto la acción de tejer como la persona que teje. El participio sirve como título profesional — ''tejedor'' — en Éxodo 28:32, 35:35 y 39:22, 27, describiendo artesanos que confeccionan vestiduras sacerdotales. El ''enjullo de tejedor'' (1 S 17:7; 2 S 21:19; 1 Cr 11:23; 20:5) se convirtió en la comparación habitual para la enorme lanza de Goliat. Isaías 59:5 extiende la imagen metafóricamente: los malvados ''tejen telas de araña''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84047, 'spa', 'Distrito en Basan', 'Nombre geografico Argob, que identifica un distrito delimitado dentro de Basan en Transjordania, celebre por sus sesenta ciudades fortificadas. El nombre posiblemente significa ''monton de terrones'' o ''region pedregosa'', acorde con el paisaje basaltico del Hauran. Deuteronomio 3:4, 13-14 lo asocia con חֶבֶל (region medida) y lo vincula con la redesignacion del area por Jair. 1 Reyes 4:13 lo situa dentro de la administracion salomonida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84049, 'spa', 'Púrpura real', 'Daniel 5:7, 16 y 29 mencionan la púrpura como parte de la recompensa ofrecida y finalmente otorgada a Daniel. El rey promete que el intérprete «será vestido de púrpura y llevará un collar de oro al cuello», honores regios que lo elevan al rango de tercer gobernante del reino. La triple repetición subraya su importancia: la púrpura marca la transferencia de estatus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84050, 'spa', 'Cofre de ofrendas', '1 Samuel 6:8, 11 y 15 describen la caja que contenía la ofrenda de oro por la culpa cuando los filisteos devolvieron el arca. Se les instruyó colocar las figuras de oro en un cofre al costado del arca, manteniendo las ofrendas separadas del arca misma, mostrando reverencia incluso en su devolución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84051, 'spa', 'púrpura (tela/tinte) — Tela y hilo teñidos de púrpura o rojo-púrpura, atestiguad', 'púrpura (tela/tinte) — Tela y hilo teñidos de púrpura o rojo-púrpura, atestiguados principalmente en las listas de textiles cúlticos del tabernáculo (Éx 25:4; 26:1, 31, 36; 27:16; 28:5–8, 15, 33; 35:6, 23, 25, 35; 36:8–37; 38:18, 23; 39:1–29) y secundariamente en contextos reales o lujosos (Jue 8:26; 2 Cr 2:6, 13; 3:14; Est 1:6; 8:15; Pr 31:22; Cnt 3:10; 7:6). Aparece casi invariablemente en la tríada formulaica ''azul, púrpura y escarlata'' (תְּכֵלֶת, אַרְגָּמָן, תּוֹלַעַת שָׁנִי).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84061, 'spa', 'Interjeccion presentativa', 'Interjeccion discursiva que significa ''he aqui'' o ''!mira!'', funcionando como marcador deictico que senala la aparicion dramatica de un nuevo elemento dentro de una secuencia visionaria. Limitada a Daniel 7:2, 5, 6, 7, 13, introduce de manera consistente cada bestia y al ''semejante a un hijo de hombre''. Las glosas multilingues la traducen uniformemente como particula presentativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84066, 'spa', 'Establos reales', '1 Reyes 4:26 indica que Salomón tenía establos para sus caballos, con variantes textuales entre 40.000 y 4.000. 2 Crónicas 9:25 registra 4.000 establos para caballos y carros, una infraestructura real masiva. 2 Crónicas 32:28 describe la riqueza de Ezequías, incluyendo almacenes y establos para toda clase de ganado. El término abarca tanto comederos como los recintos más amplios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84067, 'spa', 'sanidad, restauración', 'Sustantivo femenino que literalmente significa ''el crecimiento de carne nueva sobre una herida'', usado figuradamente para la restauración nacional y espiritual. En la literatura profética describe la sanidad prometida por Dios para Israel: brotando velozmente cuando se practica la justicia (Is 58:8, con el verbo צָמַח ''brotar''), contrastada con la ausencia de bálsamo en Galaad (Jer 8:22), y afirmada como acto soberano de restauración divina (Jer 30:17; 33:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84072, 'spa', 'arca (del Pacto)', 'El Arca del Pacto, el cofre de madera revestido de oro que contenía las tablas de piedra, la vara de Aarón y un frasco de maná. Casi todas las apariciones de este lema (197 de 202) se refieren a este objeto sagrado. Las traducciones lo distinguen uniformemente: español ''arca'', francés ''arche'', alemán ''Lade''. Pasajes clave incluyen Éxodo 25:10-22, 1 Samuel 4-6 y 2 Samuel 6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84080, 'spa', 'cofre (para dinero)', 'Un cofre utilizado para recoger ofrendas monetarias, específicamente la caja para el fondo de reparaciones del templo establecida por el sacerdote Joiada durante el reinado de Joás. La misma raíz pasa del contexto sagrado al fiscal en 2 Reyes 12:10-11 y 2 Crónicas 24:8-11. El español y el alemán mantienen el mismo término base, pero solo el contexto desambigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84081, 'spa', 'ataúd (féretro)', 'Un ataúd o sarcófago, usado una sola vez en Génesis 50:26 para el receptáculo funerario de José en Egipto. El cognado fenicio significa igualmente ''sarcófago'', lo que sugiere que esta acepción funeraria es la capa de significado más antigua. El inglés traduce ''coffin'', el español ''ataúd'' y el alemán ''Sarg'', evidenciando lo distinto de este sentido respecto al vaso sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84088, 'spa', 'Habitante jebuseo de Jerusalén que poseía la era en el monte Moriah donde el áng', 'Habitante jebuseo de Jerusalén que poseía la era en el monte Moriah donde el ángel de YHWH detuvo la plaga durante el censo de David (2 S 24:16-18). Arauna ofreció su era, bueyes y equipo como regalo para el sacrificio, pero David los compró al precio completo — cincuenta siclos de plata (2 S 24:20-24) — estableciendo el principio de que la verdadera adoración requiere un costo personal. Este sitio se convirtió en la ubicación del templo de Salomón (2 Cr 3:1). El nombre aparece como Ornán (אָרְנָן) en Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84091, 'spa', 'Cedro (árbol o madera)', 'Cedro (árbol o madera): El árbol del cedro (Cedrus libani), que abarca el árbol vivo que crece en el Líbano (Sal 104:16; Jue 9:15; Is 2:13), su madera aserrada empleada en templos, palacios y naves (1 Re 5:6-10; 6:15; Ez 27:5), y su uso ritual en ceremonias de purificación junto con el hisopo (Lv 14:4, 49-52). En sentido figurado, el cedro representa la majestad imponente (Ez 31:3-14; Nm 24:6) y, cuando es talado por Dios, la humillación del orgullo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84118, 'spa', 'Viajar o transitar', 'Caminar o ir por un sendero, usado tanto literalmente para el desplazamiento fisico como figuradamente para la asociacion o compania. En Job 34:8 אָרַח describe la acusacion de Elihu de que Job ''anda en compania'' de obradores de iniquidad. La forma participial sirve como sustantivo con el sentido de ''viajero'' o ''caminante'', alguien que pasa por un lugar sin residencia permanente. En 2 Samuel 12:4 el viajero (אֹרֵחַ) contrasta con el anfitirion asentado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84119, 'spa', 'Nombre propio Ara', 'Ara: nombre propio que identifica (a) a un descendiente de Aser en 1 Crónicas 7:39 y (b) al ancestro de una familia que regresó del exilio babilónico (Esd 2:5; Neh 7:10). El nombre posiblemente deriva de la raíz ארח «viajar», sugiriendo «viajero». La familia reaparece en Nehemías 6:18, donde Mesulam hijo de Berequías se casó con una hija de este clan, creando una alianza política con Tobías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84120, 'spa', 'Senda, camino o ruta para transitar', 'Senda, camino o ruta para transitar. Abarca vías físicas: los caminos que cesaron en los días de Samgar (Jue 5:6), la serpiente que acecha ''junto al sendero'' (Gn 49:17), el camino bloqueado por Dios (Job 19:8) y la ruta que el sol recorre por el cielo (Sal 19:5). El alemán ''Pfad'' y el francés ''sentier'' marcan consistentemente este sentido concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84121, 'spa', 'El camino de vida o la conducta moral que uno sigue', 'El camino de vida o la conducta moral que uno sigue. Es el sentido teológicamente más rico, dominante en Proverbios, Salmos y Job: ''la senda de los justos'' (Pr 4:18), ''las sendas de los impíos son tortuosas'' (Pr 2:15), Dios vigilando ''todas mis sendas'' (Job 13:27; 33:11). El español alterna entre ''senda'' y ''camino'', reflejando tanto el matiz íntimo como el más general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84140, 'spa', 'Por metonimia, un viajero o caminante — la persona que recorre la senda', 'Por metonimia, un viajero o caminante — la persona que recorre la senda. Job 31:32 dice ''al viajero (אֹרַח) abrí mis puertas'', donde la palabra para camino designa a quien lo transita. El español ''viajero'' y el inglés ''traveler'' hacen explícito el desplazamiento metonímico, una extensión semántica natural en las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84141, 'spa', 'Una caravana o grupo de viajeros — otra extensión metonímica, esta vez colectiva', 'Una caravana o grupo de viajeros — otra extensión metonímica, esta vez colectiva. Job 6:19 habla de ''las caravanas (אֹרְחוֹת) de Temá'', donde los caminos en plural se convierten en las recuas de mercaderes que los recorren. Las traducciones multilingües los vierten uniformemente como ''caravanas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84149, 'spa', 'El curso o proceso natural de las cosas — usado idiomáticamente en Gn 18', 'El curso o proceso natural de las cosas — usado idiomáticamente en Gn 18:11 donde a Sara le había cesado ''el camino (אֹרַח) de las mujeres'', es decir, la menstruación. El español ''camino'', el francés ''chemin'' y el inglés ''way'' emplean aquí sus palabras más generales para designar senderos, reflejando un eufemismo donde el curso regular de la naturaleza se denomina ''senda''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84152, 'spa', 'El recorrido personal o la rutina diaria, vistos con intimidad', 'El recorrido personal o la rutina diaria, vistos con intimidad. Sal 139:3 — ''escudriñas mi senda (אָרְחִי) y mi descanso'' — emplea la palabra para la totalidad de los movimientos y hábitos cotidianos del salmista bajo la mirada omnisciente de Dios. Aunque cercano al sentido 2, aquí el énfasis no es la evaluación moral sino el conocimiento íntimo: Dios conoce cada paso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84156, 'spa', 'ración regular de alimento', 'Ración o provisión oficial de alimento, típicamente otorgada por decreto real. En 2 R 25:30 y el paralelo de Jer 52:34, el exiliado rey Joaquín recibe una ''ración continua'' (אֲרֻחָה תָּמִיד) del rey babilónico, una provisión diaria recurrente que cierra el libro de Reyes con una nota de cautelosa esperanza. Jeremías 40:5 igualmente registra provisiones dadas a Gedalías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84161, 'spa', 'comida, porción doméstica', 'Una comida o porción de alimento en un contexto general y doméstico. En Prov 15:17, ''una comida de legumbres donde hay amor'' (אֲרֻחַת יָרָק) presenta la comida modesta como proverbio sapiencial, contrastando la sencillez con la abundancia. A diferencia del sentido de ración oficial, este uso carece de connotaciones institucionales: es simplemente una comida servida a invitados o familiares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84163, 'spa', 'león (gran felino depredador) — Un león (Panthera leo), ya sea literal o figurad', 'león (gran felino depredador) — Un león (Panthera leo), ya sea literal o figurado: el poderoso felino depredador empleado en toda la Escritura como imagen de fuerza, peligro y autoridad real. En el plano narrativo incluye el encuentro de Sansón (Jue 14:5) y la defensa de David de su rebaño (1 S 17:34, 36–37). En el figurado, la bendición de Balaam sobre Israel como león agazapado (Nm 23:24; 24:9) y los leones tallados en el trono de Salomón (1 R 10:19–20). Esta es la forma aramea más breve junto al más común אַרְיֵה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84175, 'spa', 'león — El león asiático (Panthera leo persica) como animal real encontrado en el', 'león — El león asiático (Panthera leo persica) como animal real encontrado en el paisaje bíblico y metáfora omnipresente de fuerza, realeza y poder divino. Usado literalmente en encuentros narrativos (Jue 14:5–8, Sansón; 1 R 13:24–28, el profeta desobediente; 2 S 23:20, la hazaña de Benaía). Usado figuradamente en bendiciones tribales para simbolizar destreza guerrera (Gn 49:9 ''Judá es cachorro de león''; Dt 33:22 Dan), ferocidad militar (2 S 17:10) e ira divina (Lm 3:10; Os 11:10). Con 46 ocurrencias, אַרְיֵה es el término estándar en prosa y poesía para este depredador supremo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84183, 'spa', 'Ariel', 'Nombre que significa ''león de Dios'' (de אֲרִי ''león'' + אֵל ''Dios''), usado con sentidos superpuestos: (a) como epíteto profético de Jerusalén en Isaías 29:1-2, donde Dios se dirige a la ciudad como ''Ariel'' pero amenaza con convertirla verdaderamente en un ''ariel'' (altar-hogar), un llamativo juego de palabras entre orgullo cívico y fuego sacrificial; (b) como nombre personal de un hombre principal que Esdras envió a reclutar levitas para el regreso a Jerusalén (Esd 8:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84187, 'spa', 'Hogar sacrificial', 'Ezequiel 43:15-16 describe la estructura del altar en el templo visionario, usando este término para el hogar que medía cuatro codos de alto, con cuatro cuernos que se proyectaban hacia arriba. El texto presenta las formas «harel» y «ariel», posibles variantes dialectales o un juego de palabras deliberado. El hogar representa el punto culminante del altar, donde las ofrendas se encontraban con el fuego divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84190, 'spa', 'El león como animal literal en las porciones arameas de Daniel, apareciendo excl', 'El león como animal literal en las porciones arameas de Daniel, apareciendo exclusivamente en dos contextos: el foso de los leones donde Daniel es arrojado por decreto real y del cual Dios lo libra enviando un ángel para cerrar las bocas de los leones (Dn 6:7, 12, 16-17, 19-20, 22, 24, 27), y la visión apocalíptica donde la primera bestia se asemeja a un león con alas de águila (Dn 7:4), ampliamente entendida como símbolo del Imperio babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84194, 'spa', 'Arioc (nombre propio)', 'El nombre propio Arioc (אַרְיוֹךְ), que identifica al capitán de la guardia real de Nabucodonosor en Daniel 2. Recibe la orden de destruir a los sabios de Babilonia (Dn 2:14-15), pero transmite la solicitud de audiencia de Daniel y finalmente lo escolta ante el rey (Dn 2:24-25). El nombre posiblemente deriva de un original sumerio o acadio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84196, 'spa', 'prolongar la vida o los días — El sentido causativo Hifil de prolongar la vida o', 'prolongar la vida o los días — El sentido causativo Hifil de prolongar la vida o extender los días, especialmente en la fórmula de la alianza ''para que se prolonguen tus días sobre la tierra'' (Dt 4:40; 5:33; 6:2). Este es el uso dominante de la raíz, que aparece a lo largo de Deuteronomio, Proverbios y Eclesiastés como promesa vinculada a la obediencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84199, 'spa', 'extender o estirar físicamente — El sentido causativo Hifil de estirar o extende', 'extender o estirar físicamente — El sentido causativo Hifil de estirar o extender físicamente un objeto concreto en el espacio. Isaías 54:2 ordena ''alarga tus cuerdas''; en 1 Reyes 8:8 y 2 Crónicas 5:9 las varas del arca fueron ''alargadas'' de modo que sus extremos se podían ver. El Salmo 129:3 usa la imagen de labradores que ''alargaron sus surcos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84200, 'spa', 'continuar o persistir en duración — El sentido Hifil de continuar o persistir en', 'continuar o persistir en duración — El sentido Hifil de continuar o persistir en duración: prolongar una acción, un sonido o un estado a lo largo del tiempo, sin referirse a la vida. En Números 9:19, 22 la nube ''prolongó'' su permanencia sobre el tabernáculo; en Josué 24:31 y Jueces 2:7 Israel sirvió al Señor todos los días que los ancianos ''prolongaron'' su influencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84207, 'spa', 'demorar o diferir — El sentido Hifil de demorar, diferir o ejercer paciencia con', 'demorar o diferir — El sentido Hifil de demorar, diferir o ejercer paciencia contenida. Proverbios 19:11 enseña que la prudencia hace al hombre ''lento para la ira''; en Isaías 48:9 Dios dice ''por amor de mi nombre diferiré mi ira''; Job 6:11 pregunta qué fuerzas tiene para seguir ''prolongando'' su espera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84212, 'spa', 'ser largo (estativo) — El sentido estativo del Qal que describe algo como siendo', 'ser largo (estativo) — El sentido estativo del Qal que describe algo como siendo o volviéndose largo, usado tanto para extensión temporal como física. Génesis 26:8 señala que ''los días se alargaron'' (es decir, pasó mucho tiempo); Ezequiel 12:22 cita el proverbio ''los días se prolongan''; Ezequiel 31:5 describe ramas que ''se alargaron''. Este es el estado intransitivo básico del cual derivan los sentidos causativos del Hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84224, 'spa', 'Lento para la ira, longánimo, paciente — el uso abrumadoramente dominante, que a', 'Lento para la ira, longánimo, paciente — el uso abrumadoramente dominante, que aparece 13 veces en la frase constructa אֶרֶךְ אַפַּיִם (literalmente ''largo de narices'', ya que la nariz era la sede de la ira en la antropología hebrea). Es el epíteto divino estándar en la gran fórmula teofánica revelada primero en el Sinaí (Éx 34:6) y repetida a lo largo del canon: Nm 14:18, Neh 9:17, Sal 86:15, 103:8, 145:8, Joel 2:13, Jon 4:2, Nah 1:3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84228, 'spa', 'Largo en sentido físico o espacial, describiendo extensión o dimensión', 'Largo en sentido físico o espacial, describiendo extensión o dimensión. En Ez 17:3, la gran águila es אֶרֶךְ הָאֵבֶר, ''larga de alas'', metáfora vívida del alcance imperial de Nabucodonosor. En Ec 7:8, אֶרֶךְ רוּחַ (''largo de espíritu'') tiende un puente entre la longitud física y la temperamental, significando resistencia paciente. Uso distinto del sentido idioático de ''lento para la ira''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84232, 'spa', 'Extensión prolongada', '2 Samuel 3:1 señala que «la guerra fue larga entre la casa de Saúl y la casa de David», un conflicto dilatado que lentamente trasladó el poder. Jeremías 29:28 cita al falso profeta Semaías advirtiendo que el exilio «será largo». Job 11:9 declara que la sabiduría de Dios tiene «una medida más larga que la tierra y más ancha que el mar», una inmensidad inconmensurable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84233, 'spa', 'Longitud o dimensión espacial de un objeto, utilizada abrumadoramente para medid', 'Longitud o dimensión espacial de un objeto, utilizada abrumadoramente para medidas arquitectónicas y de construcción (87 ocurrencias). Es el sentido que impregna Éxodo 25-27 (el tabernáculo), 1 Reyes 6-7 (el templo de Salomón) y Ezequiel 40-48 (el templo visionario). La fórmula fija con רֹחַב (''anchura'') aparece decenas de veces. El español longitud/largo, el francés longueur y el alemán Länge convergen en esta medición concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84238, 'spa', 'Duración temporal o longevidad, presente en la expresión fija אֹרֶךְ יָמִים (''la', 'Duración temporal o longevidad, presente en la expresión fija אֹרֶךְ יָמִים (''largura de días''). En el Salmo 21:5 el rey recibe ''largura de días por los siglos de los siglos'', y Proverbios 3:2, 16 promete que la mano derecha de la Sabiduría sostiene ''largura de días''. La metáfora proyecta la extensión espacial sobre el eje del tiempo: una vida larga es una vida prolongada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84241, 'spa', 'Paciencia, tolerancia o dominio propio en sentido figurado, presente en la expre', 'Paciencia, tolerancia o dominio propio en sentido figurado, presente en la expresión אֹרֶךְ אַפַּיִם (''largura de narices/ira'', Pr 25:15) y en contextos como Sal 91:16 y 93:5 donde está en vista la presencia divina perdurable. La metáfora corporal es vívida: la paciencia es la respiración lenta y prolongada antes de que la nariz se dilate de ira. El francés long (patience) y el alemán Langmut captan este sentido compuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84254, 'spa', 'El arquita', 'Adjetivo gentilicio que significa ''el arquita'', indicando procedencia de la ciudad de Erec o Arka cerca de Betel, cuya frontera se menciona en Joshua 16:2. Se aplica casi exclusivamente a Husai, leal consejero de David y ''amigo del rey'', quien sirvió como agente encubierto durante la revuelta de Absalón: se encontró con David en el Monte de los Olivos (2 Sam 15:32), se infiltró en la corte de Absalón (2 Sam 16:16) y logró frustrar el consejo de Ahitofel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84257, 'spa', 'Aram (nombre propio)', 'El nombre propio Aram, que designa tanto a una persona (quinto hijo de Sem, Gn 10:22-23; también nieto de Nacor, Gn 22:21) como al pueblo semítico y el territorio conocido como Aram, que abarcaba la alta Mesopotamia y Siria. En la narrativa histórica se refiere principalmente a los reinos arameos — en especial Aram-Damasco — adversarios militares frecuentes de Israel durante el período monárquico (1 Re 20:1-34; 2 Re 5-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84264, 'spa', 'palacio, residencia real — Un gran palacio o residencia real, que enfatiza esple', 'palacio, residencia real — Un gran palacio o residencia real, que enfatiza esplendor, riqueza y la sede del poder gobernante. El salmista ora por la paz ''dentro de tus palacios'' (Sal 122:7) e Isaías profetiza que el palacio de los extranjeros será reducido a escombros (Is 25:2). El uso profético suele conllevar ironía: estas magníficas estructuras que simbolizan poder serán consumidas por el fuego del juicio divino (Am 1:4, 7, 10, 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84265, 'spa', 'ciudadela, bastión fortificado — Una ciudadela o bastión fortificado, que enfati', 'ciudadela, bastión fortificado — Una ciudadela o bastión fortificado, que enfatiza la función militar defensiva. Zimri murió en la ciudadela de la casa del rey (1 R 16:18) y Pecaías fue asesinado en la ciudadela del palacio (2 R 15:25). El proverbio compara al hermano ofendido con una ciudad atrancada, con contiendas como ''los cerrojos de una ciudadela'' (Pr 18:19). Este sentido subraya la dimensión de fortaleza y defensa más que la de esplendor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84284, 'spa', 'Persona de Aram (Siria/Alta Mesopotamia), usado como adjetivo gentilicio', 'Persona de Aram (Siria/Alta Mesopotamia), usado como adjetivo gentilicio. Aplicado a Labán como «Labán el arameo» a lo largo de las narrativas patriarcales (Gn 25:20; 28:5; 31:20, 24), estableciendo la conexión familiar entre Israel y Aram. La confesión litúrgica de Deuteronomio 26:5 — «Un arameo errante fue mi padre» — convierte la identidad aramea en fundamento de la autocomprensión israelita. En los libros históricos designa a los habitantes de los reinos arameos, especialmente Damasco (2 R 5:20; 8:28-29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84288, 'spa', 'En arameo (adverbio)', 'Forma adverbial que significa ''en arameo'' o ''en lengua aramea'', designando el arameo como medio de comunicación. En 2 Reyes 18:26 (= Is 36:11) marca una frontera sociolingüística: los funcionarios judíos solicitan el arameo como lengua diplomática para mantener las amenazas del Rabsaces lejos del pueblo hebreohablante. En Esdras 4:7 indica que la correspondencia oficial fue redactada en arameo, y en Daniel 2:4 señala la transición lingüística del texto bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84289, 'spa', 'Aram-Naharáyim (topónimo)', 'El nombre geográfico Aram-Naharáyim (''Aram de los dos ríos''), que designa el territorio mesopotámico en la región del alto Éufrates. Génesis 24:10 lo identifica como destino del siervo de Abraham en busca de esposa para Isaac, anclándolo en la geografía patriarcal. Jueces 3:8 nombra a Cusán-Risataim como rey de esta región, y 1 Crónicas 19:6 registra que los amonitas contrataron carros de allí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84295, 'spa', 'Nombre propio del río y wadi (actual Wadi Mujib) que marcaba el límite norte de ', 'Nombre propio del río y wadi (actual Wadi Mujib) que marcaba el límite norte de Moab y el límite sur del territorio amorreo y posteriormente israelita en Transjordania. Frecuentemente acompañado de נַחַל (''wadi/torrente'') en Dt 2:24, 36 y Jos 12:1, enfatizando el profundo desfiladero. La Estela de Mesa confirma su importancia como marcador territorial. Las traducciones lo transliteran de forma uniforme: en español ''Arnón''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84299, 'spa', 'Ornán (hebreo אׇרְנָן) es el jebuseo que poseía la era en el monte Moriah, la cu', 'Ornán (hebreo אׇרְנָן) es el jebuseo que poseía la era en el monte Moriah, la cual David compró después de que la plaga fuera detenida por el ángel del SEÑOR (1 Cr 21:15-28). Este lugar se convirtió en el sitio del templo de Salomón (2 Cr 3:1). Es llamado Arauna (אֲרַוְנָה) en el relato paralelo de 2 Samuel 24:16-24, lo que refleja una variación dialectal o una tradición de transcripción diferente. Las doce apariciones en Crónicas se refieren a la misma persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84302, 'spa', 'Sustantivo arameo para ''tierra'' o ''suelo'', equivalente exacto del hebreo אֶרֶץ', 'Sustantivo arameo para ''tierra'' o ''suelo'', equivalente exacto del hebreo אֶרֶץ. Aparece predominantemente en las visiones apocalípticas de Daniel: la piedra que llena toda la tierra (Dn 2:35), el dominio que se extiende sobre toda la tierra (Dn 4:1; 6:26), y en la correspondencia de Esdras sobre el Dios del cielo y de la tierra (Esd 5:11). El estado enfático אַרְעָא predomina, mientras que la forma direccional produce el sentido de ''inferior'' (Dn 2:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84309, 'spa', 'Arpad (topónimo)', 'Nombre propio de una ciudad-estado en el norte de Siria (la actual Tell Erfad), que aparece exclusivamente en contextos de triunfo militar asirio. Cada mención empareja a Arpad con Hamat y a veces con otras ciudades conquistadas, funcionando retóricamente para demostrar la futilidad de resistir a Asiria (2 Kgs 18:34; 19:13; Isa 10:9; 36:19; 37:13; Jer 49:23). Los registros asirios la conocen como Arpadda, confirmando su importancia histórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84312, 'spa', 'Arfaxad (nombre propio)', 'Arfaxad — nombre propio del tercer hijo de Sem y patriarca en la línea genealógica de Noé a Abraham. Aparece en Génesis 10-11 y 1 Crónicas 1:17-24, anclando el linaje postdiluviano del pacto abrahámico. El nombre puede derivar de un referente geográfico, posiblemente Babilonia o la región de Arrapaquitis cerca de Nínive.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84316, 'spa', 'tierra, país (desglosado)', 'Tierra territorial o país, acepción dominante que abarca la geografía de la alianza (''la tierra de X''). El uso suajili de nchi (nación/país) y el hindi देश confirman este enfoque geopolítico, distinguiendo la especificidad territorial de la generalidad cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84324, 'spa', 'suelo, tierra (desglosado)', 'La tierra como orden creado, el mundo completo en el merismo ''cielo y tierra'' (Gn 1:1). Las glosas multilingües cambian a vocabulario cósmico —suajili dunia, hindi पृथ्वी, árabe الْأَرْضِ con alcance universal— distinguiéndolo del sentido territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84325, 'spa', 'mundo, orden creado', 'La tierra como orden creado, el mundo entero en el merismo ''cielos y tierra'' (Gn 1:1). Las traducciones multilingües cambian a vocabulario cósmico —suajili dunia, hindi पृथ्वी, árabe الْأَرْضِ con alcance universal— distinguiendo esta acepción del sentido territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84335, 'spa', 'tierras, territorios (plural)', 'Tierras o territorios en plural, denotando regiones o naciones dispersas. El árabe أَرَاضِي (plural fracto), el coreano 땅들 y el suajili nchi za (concordancia plural) señalan este sentido morfológica y semánticamente plural, frecuente en contextos de exilio y diáspora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84397, 'spa', 'El sentido dominante del participio pasivo', 'El sentido dominante del participio pasivo: el estado de estar bajo una maldición divina o de autoridad, que funciona casi como un adjetivo. Es el אָרוּר de las maldiciones del pacto (Dt 27:15-26), de los juicios primigenios (Gn 3:14, 17; 4:11) y de las sentencias patriarcales (Gn 9:25). El español maldito, el francés maudit y el alemán verflucht conservan la fuerza participial-adjetival. Con 40 ocurrencias, es el sentido más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84398, 'spa', 'Maldición intensiva en la conjugación Piel, que indica un acto enfático, repetid', 'Maldición intensiva en la conjugación Piel, que indica un acto enfático, repetido o ritual de maldecir, a menudo ligado a contextos ceremoniales formales. Las aguas de la maldición amarga en Números 5:18-27 emplean esta conjugación, mientras el sacerdote administra el juramento que ''acarrea maldición'' sobre la mujer sospechosa de adulterio. Génesis 5:29 la usa respecto a la tierra que Dios ''ha maldecido''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84400, 'spa', 'El sentido verbal activo', 'El sentido verbal activo: pronunciar una maldición sobre alguien, abarcando formas finitas (imperfecto, perfecto, imperativo), participios activos con el significado de ''quien maldice'' y el enfático infinitivo absoluto. Balaam es convocado para ''maldecir a este pueblo por mí'' (Nm 22:6), y Dios promete a Abraham ''al que te maldiga yo lo maldeciré'' (Gn 12:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84403, 'spa', 'Conjugaciones pasivas (Nifal y Hofal) que denotan la experiencia de ser maldecid', 'Conjugaciones pasivas (Nifal y Hofal) que denotan la experiencia de ser maldecido o convertido en maldito por un agente externo. En Nm 22:6 Balac reconoce que a quien Balaam maldice ''queda maldito'' — el resultado pasivo del acto de habla activo. Malaquías 3:9 advierte que toda la nación ''está maldita'' por robar a Dios los diezmos. Solo 2 ocurrencias, pero confirman la simetría activo-pasiva del sistema verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84418, 'spa', 'Territorio de Ararat', 'Ararat: territorio geográfico correspondiente a la antigua Urartu en la Armenia oriental, empleado como escenario de liberación divina y como entidad política. Génesis 8:4 señala «los montes de Ararat» como lugar donde reposó el arca, símbolo de la preservación de Dios en medio del juicio. En 2 Reyes 19:37 e Isaías 37:38 es el refugio de los hijos regicidas de Senaquerib, y Jeremías 51:27 lo alista como aliado contra Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84419, 'spa', 'Desposar (Piel', 'Desposar (Piel: desposorio activo). El sentido Piel (activo): desposar, contraer un compromiso matrimonial. El sujeto es siempre el varón que asegura a la novia, especificando a veces el precio pagado (2 Sam 3:14) o los dones del pacto entregados (Os 2:19-20). Deuteronomio 20:7 exime de la batalla al hombre que ha desposado esposa pero aún no se ha casado, resaltando la distinción legal entre desposorio y consumación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84420, 'spa', 'Ser desposada (Pual', 'Ser desposada (Pual: estado pasivo). El sentido Pual (pasivo): estar desposada, describiendo el estado de la mujer como alguien formalmente comprometida. Concentrado en Deuteronomio 22:23-28, donde la ley distingue cuidadosamente entre una mujer desposada y una que no lo está: la desposada está legalmente vinculada, y violarla conlleva la misma pena que el adulterio. También aparece en Éxodo 22:16 respecto a una virgen no desposada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84426, 'spa', 'Artajerjes (rey persa)', 'Artajerjes (rey persa). El nombre real persa Artajerjes, referido principalmente a Artajerjes I Longímano (465-424 a.C.), el emperador aqueménida que autorizó tanto la misión sacerdotal-escribal de Esdras a Jerusalén (Esd 7:1, 7, 11-12, 21) como la gobernación de Nehemías y su proyecto de reconstrucción de la muralla (Neh 2:1; 5:14; 13:6). También aparece en la correspondencia adversarial de Esdras 4:7-8, 11, 23, donde funcionarios provinciales persuaden al rey de detener la obra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84431, 'spa', 'Artajerjes (rey persa)', 'Nombre propio del rey persa Artajerjes en su forma ortográfica aramea. Esta variante (אַרְתַּחְשַׁשְׂתְּא / אַרְתַּחְשַׁסְתְּא) aparece en las porciones arameas de Esdras que tratan la correspondencia oficial persa sobre el proyecto de reconstrucción del templo. La evidencia multilingüe es unánime: en español ''Artajerjes'', en francés ''Artaxerxès'', en alemán ''Artahsasta'', todas identifican al mismo monarca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84435, 'spa', 'fuego, llamas físicas', 'Fuego literal y llamas físicas en toda su gama de usos prácticos: combustión, incendio, hoguera, fuego sacrificial, fuego de señales, destrucción bélica y calor doméstico. Con 345 apariciones, abarca la vasta mayoría de los casos, desde el fuego del pacto de Abraham (Gn 15:17) hasta la quema de ciudades en las narrativas de conquista (Jos 6:24; Jue 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84440, 'spa', 'fuego teofánico', 'Fuego como teofanía divina — la manifestación visible de la presencia, la gloria o el poder sobrenatural de Dios. La zarza ardiente (Éx 3:2), la columna de fuego (Éx 13:21), la gloria en el Sinaí descrita como ''fuego devorador'' (Éx 24:17) y la aparición de Dios ''en el fuego'' durante la dedicación del templo. Estas 18 apariciones comparten un perfil distintivo: el fuego se describe pero no consume lo que debería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84441, 'spa', 'fuego de juicio o ira', 'Fuego como instrumento de juicio divino, ira o castigo consumidor. La cólera de Dios ''arde como fuego'' (Jer 4:4; Ez 21:31-32); Jerusalén será devorada ''en fuego'' como sentencia (Ez 22:21); ''fuego inextinguible'' se convierte en figura del castigo divino ineludible (Is 66:24). Estas 10 apariciones se distinguen del fuego físico por su carácter metafórico o hiperbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84442, 'spa', 'relámpago o fuego celeste', 'Relámpago, fuego celeste o fuego enviado del cielo como evento meteorológico sobrenatural. El fuego que ''cayó del cielo'' en la contienda de Elías (1 Re 18:38), el fuego de Dios que consumió los rebaños de Job (Job 1:16) y el fuego que descendió sobre los que buscaban a Elías (2 Re 1:10-12). Se distingue de la teofanía porque aquí el fuego es destructivo, y del fuego físico porque su origen es celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84457, 'spa', 'Cimientos del edificio', 'Los cimientos estructurales de un edificio, específicamente del templo de Jerusalén. Se emplea en la correspondencia oficial del período persa sobre la reconstrucción del templo (Esdras 4:12, 5:16, 6:3). El término pertenece a un registro técnico administrativo, como lo indica la conservación de la forma aramea en algunos manuscritos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84458, 'spa', 'Nombre propio', 'Nombre del segundo hijo de Benjamín y del clan que desciende de él. Aparece en la genealogía de la familia de Jacob al bajar a Egipto (Génesis 46:21), en el censo de clanes benjaminitas en el desierto (Números 26:38) y en la genealogía de Crónicas (1 Crónicas 8:1). Las variantes en los manuscritos griegos reflejan las dificultades de transmisión de los nombres propios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84464, 'spa', 'Laderas o cañadas', 'Laderas montañosas o terreno de vertiente, utilizadas en inventarios geográficos de la tierra de Canaán. La palabra aparece solo en forma plural, ya sea absoluta (Josh 10:40; 12:8) para designar las laderas como una de las cuatro zonas del terreno cananeo junto con la región montañosa, el Néguev y la llanura, o en estado constructo con Pisga (Deut 3:17; 4:49; Josh 12:3; 13:20) para identificar la escarpa oriental que domina el Mar Muerto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84468, 'spa', 'El topónimo Asdod (אַשְׁדּוֹד), que designa una de las cinco ciudades-estado fil', 'El topónimo Asdod (אַשְׁדּוֹד), que designa una de las cinco ciudades-estado filisteas en la costa mediterránea. Todas las tradiciones de traducción principales conservan una transliteración cercana (esp: Asdod, fra: Asdod, deu: Ashdod), mientras que la forma con he direccional (אַשְׁדּוֹדָה, ''hacia Asdod'') aparece en 1 S 5:1 e Is 20:1. Sus 17 ocurrencias abarcan narrativas de conquista, narrativas del arca y oráculos proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84477, 'spa', 'Asdodita, de Asdod', 'Designación gentilicia para las personas o cosas asociadas con la ciudad filistea de Asdod. Se usa como singular colectivo con artículo para referirse a toda la población (Josh 13:3), como sustantivo plural para los habitantes de la ciudad durante la narrativa del arca (1 Sam 5:3, 6), y como adjetivo femenino que modifica ''mujeres'' en el relato de Nehemías sobre los matrimonios mixtos (Neh 13:23). También aparece en Neh 4:7 refiriéndose a los opositores de la reconstrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84486, 'spa', 'Término técnico del culto para un sacrificio presentado a Yahvé mediante fuego s', 'Término técnico del culto para un sacrificio presentado a Yahvé mediante fuego sobre el altar, usado predominantemente en la legislación sacerdotal de Levítico y Números. Abarca diversos tipos de ofrendas: holocaustos de animales (Lv 1:9, 13, 17), ofrendas de cereal (Lv 2:11), e incluso el incienso memorial del pan de la proposición (Lv 24:7, 9). Fuera del Pentateuco, Dt 18:1 y 1 Sam 2:28 hacen referencia al derecho de los sacerdotes sobre las porciones sacrificiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84495, 'spa', 'mujer, persona femenina', 'Mujer, persona femenina: 519 apariciones donde אִשָּׁה designa a un ser humano femenino sin referencia primaria al estado civil. Es la acepción genérica y no marcada que abarca mujeres en la narrativa, la ley, la profecía y la literatura sapiencial, desde la hija de Faraón hasta las mujeres que contribuyen al tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84499, 'spa', 'esposa, cónyuge', 'Esposa, mujer casada: 255 apariciones donde la relación matrimonial es primordial, típicamente marcada por formas constructas (''אֵשֶׁת PN''), sufijos posesivos (''אִשְׁתּוֹ'', ''su esposa'') o contextos explícitos de matrimonio. Abram lleva a Sarai ''su mujer'' a Egipto (Gn 12:5); la ley regula la relación con ''la mujer de tu prójimo'' (Lv 18:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84519, 'spa', 'cada una (distributivo)', 'Uso distributivo de ''cada una'': 5 apariciones donde אִשָּׁה funciona como pronombre distributivo que significa ''cada una'', referido a elementos emparejados. Las cinco aparecen en Éxodo 26 describiendo las cortinas del tabernáculo: ''cinco cortinas unidas una con otra'' (Éx 26:3). Refleja el uso distributivo del masculino אִישׁ (''cada uno'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84552, 'spa', 'hembra (animal)', 'Hembra de un animal: 2 apariciones, ambas en Gn 7:2, donde Noé recibe el mandato de llevar animales al arca ''macho y su hembra'' (אִישׁ וְאִשְׁתּוֹ). Esta extensión zoológica es paralela al uso de אִישׁ como ''macho'' de un animal; la fórmula de pareja aplicada a animales recuerda vívidamente el origen compartido del léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84580, 'spa', 'Asiria, la nación', 'La entidad geopolítica Asiria — tierra, imperio, pueblo y ejércitos invasores — que aparece en todos los marcos sintácticos: forma absoluta, con preposiciones (''a Asiria'', 2 Re 15:20), con conjunciones y con sufijos direccionales. Domina con 149 apariciones a lo largo de la narrativa histórica (2 Re 15:19, 29; 16:7), el juicio profético (Is 10:5; 30:31) y la visión escatológica (Zac 10:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84587, 'spa', 'Asur, el personaje', 'El ancestro personal o tribal Asur, hijo de Sem, que aparece en contextos genealógicos. En Génesis 10:22 figura entre los hijos de Sem en la Tabla de las Naciones (fuente P), y en Ezequiel 27:23 el nombre puede portar resonancias tanto personales como territoriales dentro de una lista comercial. El alemán ''Assur'' y el inglés ''Asshur'' reflejan la lectura más personal, mientras que el español y el francés tienden a usar la misma forma que para la nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84598, 'spa', 'Torta de pasas', 'Torta prensada de uvas secas, una confección compactada que se servía como alimento festivo y se usaba en contextos sacrificiales. En 2 Samuel 6:19 y 1 Crónicas 16:3, David las reparte junto con pan y carne al pueblo reunido, marcando una celebración nacional. Cantares 2:5 las emplea metafóricamente como reconstituyente para quien desfallece de amor. Oseas 3:1 las vincula directamente con ofrendas idolátricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84600, 'spa', 'Racimo (de uvas)', 'Racimo de uvas o, por extensión, de otros frutos y flores. El sentido concreto aparece en la narración de los espías, donde el famoso אֶשְׁכּוֹל עֲנָבִים (''racimo de uvas'') de Nm 13:23 era tan grande que dos hombres debían cargarlo. Gn 40:10 describe racimos madurando en el sueño del copero del faraón. Figuradamente, el Cantar de los Cantares lo emplea para racimos de flores de alheña y frutos de palmera como imágenes de belleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84609, 'spa', 'Escol', 'Nombre propio Escol, que abarca tanto al aliado amorreo de Abraham cerca de Hebrón (Gen 14:13, 24) como al Valle de Escol (Nahal Eshcol), el uadi cerca de Hebrón donde los doce espías recogieron su famoso racimo de uvas (Num 13:23-24; 32:9; Deut 1:24). El nombre mismo significa ''racimo'', y Num 13:24 deriva explícitamente el nombre del valle del racimo cortado allí. Ya sea persona o lugar, todas las referencias se sitúan en la región de Hebrón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84611, 'spa', 'Nombre y etnia', 'Nombre propio (Génesis 10:3, 1 Crónicas 1:6) y pueblo del norte (Jeremías 51:27). En Jeremías, Asquenaz es llamado a la guerra contra Babilonia junto con los reinos de Ararat y Mini, lo que sugiere una ubicación en las tierras altas armenias o en Anatolia. Las traducciones lo tratan consistentemente como nombre propio que no requiere adaptación semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84613, 'spa', 'Árbol tamarisco', 'El tamarisco, que aparece en relatos vinculados al culto o la sepultura. Abraham planta uno en Beerseba tras establecer un pacto (Génesis 21:33); Saúl se sienta bajo el tamarisco en Guibeá «en el collado» (1 Samuel 22:6); y los restos de Saúl se entierran bajo el tamarisco de Jabes (1 Samuel 31:13). Su asociación con lugares altos y entierros indica que señalaba espacios sagrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84614, 'spa', 'ser o hacerse culpable — Incurrir en culpa ante Dios mediante una transgresión e', 'ser o hacerse culpable — Incurrir en culpa ante Dios mediante una transgresión específica, especialmente en contextos cúlticos y legales. Este es el sentido dominante del Qal que abarca casi todas las ocurrencias. Levítico 4:13–27 y 5:2–5 lo usan repetidamente como detonante de las ofrendas por la culpa: una vez que la persona ''se hace culpable'', se requiere el remedio sacrificial. Números 5:6–7 lo asocia con la confesión y la restitución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84621, 'spa', 'declarar o considerar culpable — Hifil causativo', 'declarar o considerar culpable — Hifil causativo: declarar o considerar culpable, pronunciar a alguien como responsable. Esta forma rara aparece en el Salmo 5:10, donde David pide que Dios ''los declare culpables'', una petición judicial que solicita la condenación divina de los malvados. Es la contraparte forense del sentido experiencial del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84630, 'spa', 'sufrir desolación o castigo — Sufrir desolación como consecuencia de la culpa, u', 'sufrir desolación o castigo — Sufrir desolación como consecuencia de la culpa, un sentido pasivo del Niphal que se encuentra en Joel 1:18, donde el ganado ''sufre'' o ''es asolado''. Este sentido extiende el rango semántico desde el acto de incurrir en culpa hasta soportar sus consecuencias devastadoras, mostrando cómo la raíz conecta la ofensa con su desenlace.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84635, 'spa', 'reconocer la culpa — Reconocer o admitir la propia culpa, un matiz cognitivo-ref', 'reconocer la culpa — Reconocer o admitir la propia culpa, un matiz cognitivo-reflexivo del Qal que aparece en Oseas 5:15, donde Dios espera hasta que el pueblo ''reconozca su culpa'' y busque su rostro. Este sentido es teológicamente significativo: marca el punto de giro de la culpa como estado hacia la culpa como camino de arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84639, 'spa', 'ofrenda por la culpa (sacrificio) — La ofrenda por la culpa como rito sacrificia', 'ofrenda por la culpa (sacrificio) — La ofrenda por la culpa como rito sacrificial específico, prescrito principalmente en Levítico 5–7 y Números 6:12; 18:9. A diferencia de la ofrenda por el pecado, el אָשָׁם aborda ofensas donde la restitución es posible: violaciones de cosas sagradas, tratos falsos con el prójimo o culpa incierta (Lv 5:6, 15–16; 14:12). Ezequiel lo proyecta hacia el templo restaurado (Ez 40:39; 42:13; 46:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84645, 'spa', 'compensación por la culpa — El pago de compensación o restitución debido por una', 'compensación por la culpa — El pago de compensación o restitución debido por una transgresión: el ajuste material de la culpa. Números 5:7–8 prescribe que el ofensor debe confesar y luego devolver ''su culpa'' (אֲשָׁמוֹ) íntegramente más un quinto a la parte agraviada; si esta no tiene pariente, la restitución va al sacerdote. Este sentido capta la dimensión transaccional: la culpa no solo se siente o se expía, sino que se repaga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84653, 'spa', 'culpa u ofensa — El estado abstracto de culpa o la ofensa en sí', 'culpa u ofensa — El estado abstracto de culpa o la ofensa en sí: la transgresión que crea responsabilidad ante Dios o ante el hombre. Abimelec protesta que tomar a Rebeca podría haber ''traído culpa sobre nosotros'' (Gn 26:10). El salmista declara que Dios herirá la ''cabeza culpable'' (Sal 68:21). Proverbios 14:9 observa que ''los necios se burlan de la culpa''. Jeremías 51:5 dice que la tierra de los caldeos ''está llena de culpa'' ante el Santo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84658, 'spa', 'Culpable ante Dios', 'La condición de culpa que requiere expiación. Los hermanos de José declaran «somos culpables respecto a nuestro hermano» (Génesis 42:21), reconociendo su ofensa. En el reinado de David se presenta un caso sobre cargar con la culpa (2 Samuel 14:13). Los exiliados que habían tomado mujeres extranjeras son «culpables» y deben ofrecer un carnero como ofrenda por la culpa (Esdras 10:19), mostrando la dimensión ritual del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84659, 'spa', 'El estado o condición de ser culpable, la responsabilidad contraída por las tran', 'El estado o condición de ser culpable, la responsabilidad contraída por las transgresiones ante Dios o la comunidad del pacto. Levítico 4:3 y 6:5-7 enmarcan esto en la ley sacrificial, donde la culpa debe resolverse mediante una ofrenda. Esdras 9:6-15 y 10:10-19 lo usan repetidamente para la culpa colectiva de Israel en los matrimonios mixtos. El español ''culpa'' y el francés ''culpabilité'' preservan el peso jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84668, 'spa', 'Ofensas o actos culpables concretos — las transgresiones mismas y no el estado a', 'Ofensas o actos culpables concretos — las transgresiones mismas y no el estado abstracto de culpabilidad. En 2 Crónicas 28:10, se acusa a los israelitas de ''ofensas'' (plural אַשְׁמוֹת) contra el Señor, señalando actos específicos de iniquidad. El español ''culpas'' (plural) y el cambio hacia la enumeración concreta distinguen este sentido del más abstracto ''culpabilidad'' — aquí el enfoque recae sobre lo que se hizo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84677, 'spa', 'Vigilia nocturna', 'División de las horas de la noche, típicamente una de las tres vigilias en que se repartía la noche israelita para tareas de guardia o medición del tiempo. El español ''vigilia'' conserva el doble sentido de estar alerta y de un período medido de oscuridad. Las formas constructas — ''vigilia de la mañana'' (Éx 14:24; 1 S 11:11), ''la vigilia de en medio'' (Jue 7:19) — especifican períodos particulares de la noche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84687, 'spa', 'Encantador o astrólogo', 'Practicante de artes adivinatorias o mágicas en la corte real babilónica, usado exclusivamente en las porciones arameas de Daniel. El término aparece junto a otras categorías profesionales —magos, caldeos, adivinos— cuando Nabucodonosor y Belsasar convocan a sus sabios para interpretar sueños o señales (Dan 2:10, 27; 4:7; 5:7, 11, 15). Probablemente es un préstamo del acadio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84692, 'spa', 'Aljaba', 'Carcaj para flechas portado por guerreros, empleado en descripciones militares y aplicaciones metafóricas. Literalmente designa equipo de batalla: la aljaba resonando sobre el caballo (Job 39:23), Elam descubriendo su aljaba (Isa 22:6), y la de Babilonia comparada con un sepulcro abierto (Jer 5:16). Figuradamente, el Salmo 127:5 compara a los hijos con flechas en una aljaba llena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84699, 'spa', 'Muladar, basurero', 'Montón de cenizas, estiércol o desechos que sirve tanto como lugar concreto como símbolo poderoso de pobreza y degradación. El español ''muladar'' y ''basura'' cubren el espectro desde el vertedero formal hasta los desperdicios en general. El término aparece en dos agrupaciones contextuales: como símbolo de bajeza extrema de la cual Dios levanta al necesitado (1 S 2:8; Sal 113:7; Lm 4:5), y como referencia topográfica en las murallas de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84703, 'spa', 'La ciudad filistea costera de Ascalón, una de las cinco ciudades de la pentápoli', 'La ciudad filistea costera de Ascalón, una de las cinco ciudades de la pentápolis filistea. Aparece en relatos de conquista (Jue 1:18), las hazañas de Sansón (Jue 14:19), el lamento de David (2 S 1:20) y oráculos proféticos de juicio (Am 1:8; Sof 2:4; Zac 9:5). Las doce apariciones designan un único topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84710, 'spa', 'Declarar a alguien bienaventurado, dichoso o afortunado — el sentido más frecuen', 'Declarar a alguien bienaventurado, dichoso o afortunado — el sentido más frecuente. Cuando Lea nombra a su hijo Aser diciendo ''las mujeres me llamarán bienaventurada'' (Gn 30:13), usa esta forma Piel. Aparece en contextos de sabiduría y alabanza: los hijos de la mujer virtuosa ''la llaman bienaventurada'' (Pr 31:28), y las naciones bendicen al rey justo (Sal 72:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84712, 'spa', 'Guiar, dirigir o conducir a alguien por un camino', 'Guiar, dirigir o conducir a alguien por un camino. Isaías 3:12 advierte que los líderes del pueblo ''los guían por mal camino'', e Isaías 9:16 condena a los guías que extravían. Proverbios 23:19 exhorta: ''dirige tu corazón por el camino''. El vínculo semántico con el sentido 1 es la idea de poner a alguien en el camino recto — ya sea guiándolo literalmente o bendiciéndolo metafóricamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84714, 'spa', 'Corregir, enderezar o reprender — una aplicación moral-judicial de ir derecho', 'Corregir, enderezar o reprender — una aplicación moral-judicial de ir derecho. Isaías 1:17 ordena ''corregid al opresor'' (o ''haced justicia al oprimido''), usando el verbo para significar restaurar la justicia. Este sentido tiende un puente entre el físico ''enderezar'' y el social ''hacer lo correcto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84717, 'spa', 'El pasivo Pual de declarar bienaventurado', 'El pasivo Pual de declarar bienaventurado: ser llamado bienaventurado, ser declarado dichoso por otros. El Salmo 41:2 promete que quien considera al pobre ''será llamado bienaventurado en la tierra'', y Proverbios 3:18 dice que quienes abrazan la sabiduría son bienaventurados. El pasivo transforma la declaración activa en un estado recibido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84719, 'spa', 'El pasivo Pual de guiar o dirigir', 'El pasivo Pual de guiar o dirigir: ser guiado o dirigido por otro. Isaías 9:16 habla de aquellos ''guiados por ellos'' que son extraviados — la contraparte pasiva del sentido 2. Esta es la única ocurrencia clara de pasivo-de-guía, distinta del pasivo-de-bendición en el sentido 3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84723, 'spa', 'Caminar derecho, avanzar o proseguir — el significado físico raíz del cual se de', 'Caminar derecho, avanzar o proseguir — el significado físico raíz del cual se desarrollan los demás sentidos. Proverbios 4:14 advierte ''no avances por el camino de los impíos'', y Proverbios 9:6 invita: ''caminad por el camino del entendimiento''. El cognado asirio asharu (ir derecho) confirma este como el significado base.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84728, 'spa', 'pronombre relativo (que)', 'Función de pronombre relativo nuclear, que abarca cerca del 98% de todas las apariciones. אֲשֶׁר introduce una oración subordinada que modifica un antecedente definido: ''el firmamento que Dios hizo'' (Gn 1:7), ''todo lo que había hecho'' (Gn 2:2). Sirve tanto para personas (''quien'') como para cosas (''que'') y posesivos (''cuyo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84740, 'spa', 'relativo sustantivado (lo que)', 'Uso sustantivado o sin antecedente expreso: ''lo que'', ''aquello que'', ''cualquier cosa que''. אֲשֶׁר carece de antecedente explícito y ocupa el lugar del sustantivo. En Gn 27:8 Rebeca ordena a Jacob ''haz lo que yo te mando''; en Gn 41:25 José dice al Faraón ''lo que Dios va a hacer se lo ha revelado''. El español lo que distingue esta acepción del relativo con antecedente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84763, 'spa', 'conjunción causal (porque)', 'Fuerza de conjunción causal: ''porque'', ''por lo cual'', ''por tanto''. Una sola aparición clara en Sal 95:11, donde Dios jura en su ira respecto a quienes le probaron: ''por lo cual juré en mi furor''. El español por lo cual capta la conexión lógico-causal. Representa una extensión extrema del relativo hacia el territorio de la fundamentación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84764, 'spa', 'conjunción temporal (cuando)', 'Fuerza de conjunción temporal: ''cuando''. El único caso claro es Sal 139:15, que describe al salmista siendo formado en secreto ''cuando fui hecho en lo más profundo de la tierra''. El español cuando capta el marco temporal. Como la acepción 3, es una extensión marginal pero real de la partícula relativa hacia un ámbito donde el hebreo más comúnmente emplea כִּי o בְּ + infinitivo constructo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84765, 'spa', 'Conjunción locativa que significa ''en el lugar donde'' o ''dondequiera que'', intro', 'Conjunción locativa que significa ''en el lugar donde'' o ''dondequiera que'', introduciendo una cláusula espacial. Este sentido más frecuente (9 ocurrencias) aparece en la magnífica promesa de lealtad de Rut: ''dondequiera que tú vayas, yo iré, y dondequiera que tú mores, yo moraré'' (Rut 1:16), y en la narración del levita que vagaba ''dondequiera que pudiera encontrar lugar'' (Jue 17:8-9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84766, 'spa', 'Conjunción causal que significa ''porque, por cuanto, en tanto que'', introduciend', 'Conjunción causal que significa ''porque, por cuanto, en tanto que'', introduciendo una razón o fundamento para la declaración precedente. Con 5 ocurrencias, este sentido explica por qué el amo de José confiaba en él — ''por cuanto el SEÑOR estaba con él'' (Gn 39:9, 23) — y los marineros de Jonás exigen saber ''por causa de quién'' ha venido la tormenta (Jon 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84769, 'spa', 'Conjunción relativa que significa ''en el/la cual, en lo que, con respecto a lo c', 'Conjunción relativa que significa ''en el/la cual, en lo que, con respecto a lo cual'', introduciendo una cláusula de especificación. Cinco ocurrencias se agrupan en Isaías y Eclesiastés: ''¿Qué provecho tiene el trabajador en lo que se afana?'' (Ec 3:9), y Dios juzgará a Israel ''en las cosas en las cuales no se deleitaron'' (Is 65:12; 66:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84776, 'spa', 'Función relativa de origen', 'Función relativa de origen: me''asher introduce una cláusula relativa regida por la preposición separativa min, produciendo ''de lo cual'', ''de quien'' o ''del lugar de donde''. En Gn 31:1 la riqueza que Jacob obtuvo ''de lo que pertenecía a nuestro padre'' usa esta construcción, y en Ex 29:27 las porciones sacerdotales provienen ''de lo que'' era el carnero de consagración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84778, 'spa', 'Función comparativa', 'Función comparativa: min lleva su fuerza de ''más que'' a través de la cláusula relativa, produciendo construcciones como ''más que los que'' o ''que lo que''. Las piedras de granizo mataron más que la espada (Jos 10:11); Sansón mató más en su muerte que en vida (Jue 16:30). Ec 3:22 y otros pasajes sapienciales usan esta construcción para comparaciones reflexivas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84783, 'spa', 'Función de conjunción causal', 'Función de conjunción causal: me''asher se ha gramaticalizado como conjunción subordinante que significa ''porque'' o ''puesto que'', introduciendo una cláusula de razón. En Is 43:4 Dios declara ''puesto que eres precioso a mis ojos'', y en Nm 6:11 el nazareo ofrece un sacrificio ''porque pecó''. Este desarrollo muestra cómo una preposición espacial puede derivar hacia la subordinación lógica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84787, 'spa', 'como, así como', 'Comparativo: ''como'', ''así como'', ''tal como'' — la acepción dominante con aproximadamente el 83% de las apariciones, que establece correspondencia entre dos situaciones. La fórmula כַּאֲשֶׁר צִוָּה (''como [el SEÑOR] mandó'') se repite a lo largo del Pentateuco (Gn 7:9, 7:16, Éx 39:1). El francés comme y el alemán wie lo traducen uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84788, 'spa', 'cuando (temporal)', 'Temporal: ''cuando'', ''al tiempo que'' — introduce una cláusula de tiempo. Abram entró en Egipto ''cuando'' se acercaba (Gn 12:11), y el SEÑOR se retiró ''cuando'' terminó de hablar (Gn 18:33). El español cuando y el alemán als marcan con claridad esta lectura temporal, diferenciándola del comparativo como/wie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84789, 'spa', 'y como (comparativo coordinado)', 'Comparativo coordinado: ''y como'', ''y así como'' — la acepción comparativa precedida por la conjunción waw. Funcionalmente idéntica a la acepción 1, pero dentro de cláusulas coordinadas como ''y como habéis obrado con bondad'' (Gn 26:29). El francés et-comme y el alemán und-wie reflejan la estructura de conjunción más comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84796, 'spa', 'y cuando (temporal coordinado)', 'Temporal coordinado: ''y cuando'' — la acepción temporal precedida por waw. Solo tres apariciones, incluyendo ''y cuando Moisés alzaba su mano'' (Éx 17:11) y ''y cuando vuestros siervos pregunten'' (Ez 37:18). El español y cuando y el alemán und als marcan tanto la coordinación como la temporalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84797, 'spa', 'conforme a lo que', 'Conformidad: ''conforme a lo que'', ''según lo que'' — expresa cumplimiento de un estándar o instrucción. La hija de Jefté dice ''haz conmigo conforme a lo que ha salido de tu boca'' (Jue 11:36). El español conforme a lo que aísla este matiz de conformidad respecto de la simple comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84799, 'spa', 'porque, puesto que', 'Causal: ''porque'', ''puesto que'', ''dado que'' — proporciona la razón de la cláusula principal. En Jos 6:22 y 2 Re 17:26, כַּאֲשֶׁר introduce el fundamento de una acción. El español porque y el alemán weil señalan la causalidad de manera inequívoca, confirmando que se trata de una acepción distinta y no de una lectura comparativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84805, 'spa', 'después de (secuencia)', 'Secuencia temporal: ''después de'' — indica que la cláusula principal sigue al evento subordinado. Una sola aparición en el Sal 51:1 (título: ''después de haber entrado a Betsabé''). El español cuando y el alemán nach expresan el sentido secuencial, distinguiéndolo del ''cuando'' de simultaneidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84811, 'spa', 'bienaventurado, dichoso, feliz — Interjección de bienaventuranza en forma de con', 'bienaventurado, dichoso, feliz — Interjección de bienaventuranza en forma de constructo plural, invariablemente al inicio de la oración, que declara a una persona o grupo genuinamente afortunado o bendecido por su relación con Dios, su conducta moral o la recepción del favor divino. Abre el Salterio (Sal 1:1) y recurre a lo largo de los salmos y la literatura sapiencial como fórmula fija: ''אַשְׁרֵי + la persona que...'' (Sal 32:1–2; 34:8; 84:5, 12; 112:1; 128:1). Proverbios lo aplica a la sabiduría: ''Bienaventurado el que halla la sabiduría'' (Pr 3:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84819, 'spa', 'Aser, tribu israelita — nombre propio del octavo hijo de Jacob por Zilpa (Gn 30', 'Aser, tribu israelita — nombre propio del octavo hijo de Jacob por Zilpa (Gn 30:13), cuyo significado es ''feliz'' o ''dichoso'', y de la tribu que ocupó la fértil costa noroeste desde el Carmelo hasta Sidón (Jos 19:24-31). La bendición de Jacob le promete ''pan sustancioso'' y ''manjares reales'' (Gn 49:20). También aparece una vez como lugar al este de Siquem (Jos 17:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84829, 'spa', 'Paso, pisada', 'Paso o pisada entendida figuradamente como el curso de vida o la dirección moral de una persona. El español ''pasos'' y el inglés ''steps'' convergen en la metáfora que va de lo físico a lo ético, mientras que el francés ''marche'' enfatiza la naturaleza continua del camino. Cada aparición es poética y lleva sufijo posesivo: ''mis pasos'' (Sal 17:5; 40:2; 44:18; 73:2), ''sus pasos'' (Job 23:11; Sal 37:31), reflejando la dimensión íntima del andar con Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84838, 'spa', 'Poste de Asera / árbol sagrado — el objeto físico de culto', 'Poste de Asera / árbol sagrado — el objeto físico de culto: un poste de madera, imagen tallada o árbol sagrado estilizado erigido junto a altares cananeos y lugares altos israelitas. El emparejamiento constante con ''lugares altos'' y ''altares de Baal'' recorre todas las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84840, 'spa', 'Asera (diosa) — la diosa cananea en sí, consorte de El y rival del culto a YHWH,', 'Asera (diosa) — la diosa cananea en sí, consorte de El y rival del culto a YHWH, referida donde el nombre designa a la deidad y no a su artefacto. Dt 16:21 prohíbe plantar una Asera ''junto al altar del SEÑOR''; en 1 R 15:13, Maaca es depuesta como reina madre por hacer una imagen abominable para Asera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84860, 'spa', 'Clan manasita', 'Familia o clan de Manasés contado en el censo del desierto (Números 26:31), que recibió herencia territorial en el occidente de Manasés (Josué 17:2) y aparece en las genealogías de Crónicas (1 Crónicas 7:14). El nombre funciona principalmente como designación de clan, no como biografía individual, algo típico de los registros censales tribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84864, 'spa', 'Estaol (topónimo)', 'Nombre propio de una ciudad en la región de la Sefela, emparejada consistentemente con Zora tanto en las listas de asignación tribal como en las narrativas danitas. Aparece en la asignación de Judá (Jos 15:33) y de Dan (Jos 19:41), y es escenario central de los relatos de Sansón y la migración danita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84869, 'spa', 'Estemoa (topónimo)', 'Nombre propio que designa una ciudad levítica asignada a los sacerdotes de Judá, en la serranía al sur de Hebrón (moderna es-Samu''). Aparece entre las ciudades de Judá (Jos 15:50, como «Estemoh»), designada ciudad levítica (Jos 21:14; 1 Cr 6:42), y como receptora del botín de David (1 Sam 30:28). En 1 Cr 4:17, 19 aparece como nombre personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84874, 'spa', 'Señales milagrosas', 'Señales o prodigios realizados por Dios, atestiguados por reyes gentiles. Nabucodonosor exclama ''¡cuán grandes son sus señales!'' (Daniel 4:2-3) y Darío proclama que Dios ''hace señales y maravillas'' (Daniel 6:27). El término arameo aparece en edictos reales que reconocen el poder divino, sugiriendo manifestaciones públicas e innegables que obligan incluso a gobernantes paganos a reconocer al Dios de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84875, 'spa', 'marcador de objeto directo definido', 'El marcador de objeto directo definido, antepuesto a sustantivos determinados (por artículo, constructo, nombre propio o sufijo). Intraducible en la mayoría de idiomas meta — inglés, francés y alemán lo dejan sin marcar, mientras que el español a veces usa la preposición acusativa «a». Su altísima frecuencia (10,915x) refleja cuán omnipresentes son las construcciones verbales transitivas en la narrativa y legislación del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84897, 'spa', 'con, junto a (preposición)', 'Preposición que significa «con, junto a, en compañía de», homográfica pero funcionalmente distinta del marcador de objeto. Se encuentra 62 veces en contextos de acompañamiento o proximidad, como en Núm 5:19 y Sal 31:7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84913, 'spa', 'con (compañía)', 'Comitativo: ''con'', indicando compañía, asociación o unión, acepción dominante con 665 apariciones. Noé entró al arca ''con sus hijos'' (Gn 7:7); Dios se acordó de Noé y todos los animales ''con él'' (Gn 8:1); Dios estableció su pacto ''con Noé'' (Gn 9:8). El español con y el alemán mit son los equivalentes estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84914, 'spa', 'de con (fuente ablativa)', 'Fuente ablativa con prefijo מִן: ''de con'', ''de parte de'', ''de la presencia de'' — 165 apariciones donde מֵאֵת indica origen o partida de la cercanía o autoridad de alguien. ''El SEÑOR hizo llover azufre de parte del SEÑOR desde el cielo'' (Gn 19:24); Esaú salió ''de la presencia de'' Isaac (Gn 27:30); esclavos adquiridos ''de con'' extranjeros (Gn 17:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84923, 'spa', 'marca de objeto directo', 'Marca de objeto directo (solapamiento ortográfico): partícula gramatical que señala el objeto directo definido — 50 apariciones donde las formas sufijadas de אֵת comitativo se han fusionado ortográficamente con la marca de objeto אֶת. Esto es especialmente frecuente en la prosa bíblica tardía (Josué–Reyes, Jeremías, Ezequiel).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84944, 'spa', 'cerca de, junto a', 'Proximidad espacial: ''cerca de'', ''junto a'', ''en poder de'' — 8 apariciones donde אֵת indica cercanía física más que compañía activa. Los vestidos de Rebeca estaban ''con ella'' en casa (Gn 27:15, es decir, en su posesión); a Moisés se le dice ''hay un lugar junto a mí'' (Éx 33:21). El árabe عِنْدَ (''en, cerca de'') es el paralelo semántico más preciso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84951, 'spa', 'con (adversativo, contra)', 'Sentido adversativo o contrastivo de ''con'' (contra): acepción marginal que aparece en Gn 14:9, donde los reyes hacen guerra ''con'' (es decir, contra) otros reyes — ''Quedorlaomer... con Tidal... con Amrafel... con Arioc: cuatro reyes contra cinco''. El matiz adversativo surge del contexto más que de un significado léxico separado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84968, 'spa', 'Reja de arado', 'Instrumento cortante de hierro para la agricultura, identificado como reja de arado o azadón. La visión profética de Isa 2:4 y Mic 4:3 —forjar espadas en rejas de arado (אִתִּים)— convierte esta palabra en símbolo de paz, mientras Joel 3:10 invierte la imagen. En 1 Sam 13:20-21 aparece en contexto cotidiano: los israelitas afilaban sus azadones en forjas filisteas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84971, 'spa', 'Marcador de objeto directo', 'Probable error de etiquetado en 2 Re 6:5, donde la forma וְאֶת parece ser el marcador común de objeto directo hebreo (אֵת) y no el sustantivo agrícola. Las glosas en todos los idiomas —inglés «and», español «y», alemán «und», francés «et»— lo tratan uniformemente como conjunción o partícula, confirmando que no pertenece a este lexema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84974, 'spa', 'Venir o llegar — el sentido básico del Qal que expresa movimiento hacia un lugar', 'Venir o llegar — el sentido básico del Qal que expresa movimiento hacia un lugar o persona, usado casi exclusivamente en poesía y prosa elevada. Abarca teofanías (''El SEÑOR vino de Sinaí'', Dt 33:2), experiencia personal (''lo que temía me ha sobrevenido'', Job 3:25) y convocatorias proféticas (Is 21:12). Con 16 apariciones, mantiene un registro solemne y elevado que lo distingue del más común בּוֹא.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84980, 'spa', 'Cosas venideras, eventos futuros — el participio femenino plural del Qal usado c', 'Cosas venideras, eventos futuros — el participio femenino plural del Qal usado como sustantivo en el discurso profético para designar lo que está por venir. Las 3 apariciones se concentran en la polémica de Isaías contra los ídolos, desafiando a los dioses falsos a predecir el futuro: ''Decidnos las cosas venideras'' (Is 41:23; cf. 44:7; 45:11). Es un término técnico para la predicción profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84985, 'spa', 'Traer — el causativo Hifil, que significa hacer que alguien o algo venga a un lu', 'Traer — el causativo Hifil, que significa hacer que alguien o algo venga a un lugar. Solo 2 apariciones: llevar agua al sediento fugitivo (Is 21:14) y congregar a las bestias del campo para que vengan a devorar (Jer 12:9). Este raro sentido completa el perfil de la raíz: intransitivo ''venir'' en Qal, causativo ''traer'' en Hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84989, 'spa', 'Venir, llegar a un lugar — sentido básico Peal (Qal) de movimiento hacia una met', 'Venir, llegar a un lugar — sentido básico Peal (Qal) de movimiento hacia una meta. Se usa para funcionarios que llegan a interrogar a los constructores (Esd 5:3), dignatarios convocados a una dedicación real (Dan 3:2, 26), y de manera memorable para el hijo de hombre ''viniendo con las nubes del cielo'' (Dan 7:13). Siete ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84990, 'spa', 'Traer o buscar — sentido Hafel (causativo), donde el sujeto hace que alguien o a', 'Traer o buscar — sentido Hafel (causativo), donde el sujeto hace que alguien o algo venga. Belsasar ordena que traigan los vasos de oro del templo de Jerusalén (Dan 5:2-3), y Daniel es traído ante el rey desde el exilio (Dan 5:13). Siete ocurrencias con esta fuerza transitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (84996, 'spa', 'Ser traído — Hofal (causativo pasivo), que indica que el sujeto es transportado ', 'Ser traído — Hofal (causativo pasivo), que indica que el sujeto es transportado o entregado sin actuar. Daniel es ''traído'' y arrojado al foso de los leones (Dan 6:17), y una piedra se coloca sobre la abertura. Solo dos ocurrencias, ambas en momentos de alto dramatismo narrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85001, 'spa', 'tú (pronombre 2ms)', 'Pronombre independiente de segunda persona masculino singular, empleado como sujeto autónomo o como refuerzo enfático de un sufijo pronominal. Abarca las 743 ocurrencias, incluidas las formas conjuntivas (we-attah, ''y tú''). Se usa en el discurso divino (Gn 3:14), fórmulas de pacto (Gn 6:18) y confrontación profética, siempre denotando la misma persona gramatical sin subdivisiones semánticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85010, 'spa', 'Pronombre de segunda persona singular en una forma ortográfica arcaica que termi', 'Pronombre de segunda persona singular en una forma ortográfica arcaica que termina en yod, atestiguada en lecturas ketiv en Jueces 17:2, 1 Reyes 14:2, 2 Reyes 4:16, 23, 8:1, Jeremías 4:30 y Ezequiel 36:13. Los masoretas sistemáticamente indican que se lea la forma estándar en voz alta, lo que sugiere que esta grafía refleja una pronunciación dialectal o arcaica semejante al cognado siríaco. Funcionalmente idéntica a la forma estándar del pronombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85018, 'spa', 'tú (fem', 'tú (fem. sg.) — Pronombre personal independiente de segunda persona femenino singular, empleado para dirigirse directamente a una mujer. Aparece en discursos decisivos dirigidos a mujeres a lo largo de la Biblia hebrea (Gn 12:11, 13; 24:23, 60; Rt 3:11). Tres pasajes (Nm 11:15; Dt 5:24; Ez 28:14) lo usan con referentes masculinos, probablemente por influencia aramea en la convergencia de género de este pronombre. Todos los idiomas de destino lo traducen con el pronombre estándar de segunda persona singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85029, 'spa', 'vosotros (pronombre 2ª pl.)', 'El pronombre independiente de segunda persona masculino plural, empleado para la interpelación directa y enfática a un grupo. Aparece en confrontaciones narrativas (Gn 42:9, 14), estipulaciones legales y oráculos proféticos. En ocasiones se coloca después del verbo para énfasis retórico (Jue 15:12). Las lenguas con distinción T-V (francés vous, alemán ihr) seleccionan uniformemente la forma plural, confirmando su referencia exclusivamente plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85034, 'spa', 'Vosotras (pronombre femenino)', 'El pronombre independiente de segunda persona femenino plural (אַתֵּנָה / אַתֵּן), usado para dirigirse a un grupo de referentes gramaticalmente femeninos. En Génesis 31:6 se dirige a Lea y Raquel. En Ezequiel 13:11, 20 interpela a las falsas profetisas, mientras que Ezequiel 34:17, 31 se dirige al rebaño de Dios con gramática femenina que concuerda con צֹאן (''rebaño'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85035, 'spa', 'Burra, asna — la hembra del asno, animal doméstico valorado para montar, transpo', 'Burra, asna — la hembra del asno, animal doméstico valorado para montar, transportar carga y criar. Destaca en el relato de Balaam, donde la burra ve al ángel y habla (Nm 22:21-33), en los inventarios patriarcales de riqueza (Gn 12:16; 32:15; Job 1:3; 42:12), y en la profecía mesiánica de Zacarías 9:9, donde el rey viene sobre el pollino hijo de una asna. El término distingue específicamente el género frente a חֲמוֹר.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85049, 'spa', 'Horno (cámara de fuego)', 'Horno (cámara de fuego). Un horno o kiln grande capaz de producir calor intenso, usado exclusivamente en la narrativa de Daniel 3 sobre la prueba de los tres exiliados judíos. El horno (אַתּוּן דִּי נוּרָא יָקִדְתָּא, «horno de fuego ardiente») funciona como instrumento de ejecución de Nabucodonosor para quienes desafían su decreto idolátrico (Dn 3:6, 11, 15, 17, 20-21, 23, 26). La liberación milagrosa — cuatro figuras caminando ilesas dentro — demuestra el poder de Dios sobre el elemento más destructivo a disposición del imperio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85053, 'spa', 'Galería del templo', 'Término arquitectónico (אַתִּיק) que designa galerías, terrazas o repisas escalonadas en el complejo del templo visionario de Ezequiel. En Ezequiel 42:3 las galerías se enfrentan unas a otras a través de un patio, mientras que 42:5 señala que las cámaras superiores eran más estrechas porque las galerías consumían espacio. Ezequiel 41:15-16 describe las galerías en relación con las medidas interiores del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85054, 'spa', 'Itai (nombre propio)', 'Itai — nombre propio (quizá ''conmigo'' o ''compañero'') que designa a dos hombres vinculados a David. El portador principal es Itai el gitita, un filisteo de Gat que juró lealtad inquebrantable a David durante la rebelión de Absalón (2 S 15:19-22) y recibió el mando de un tercio de las fuerzas de David (2 S 18:2). El segundo es Itai hijo de Ribai, de Gabaa de Benjamín, uno de los treinta valientes de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85056, 'spa', 'Campamento de Etam', 'Nombre propio que designa un campamento en el borde del desierto egipcio. Las cuatro apariciones se concentran en el itinerario del éxodo (Éx 13:20; Nm 33:6–8), y las traducciones multilingües transliteran uniformemente el nombre, confirmando un único referente: el asentamiento limítrofe donde Israel acampó antes de volverse hacia el mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85057, 'spa', 'Ayer, anteriormente', 'Significa ''ayer'' en sentido literal o ''anteriormente / en tiempos pasados'' de manera más amplia. La frase temol shilshom (''ayer y hace tres días'') funciona como modismo para ''previamente, como en el pasado'', y aparece en relatos sobre Saúl (1 S 10:11; 14:21) y David (2 S 5:2). El español ayer y el alemán gestern conservan el sentido concreto de ''ayer'', mientras que el francés autrefois capta la extensión temporal más general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85064, 'spa', 'Paga de ramera, salario de prostituta', 'Paga de ramera, salario de prostituta. El pago o tarifa entregada a una prostituta por servicios sexuales, usado tanto literalmente como en metáfora profética para los ingresos de la adulteración espiritual y la idolatría. Deuteronomio 23:18 lo prohíbe del tesoro del templo junto con «el precio de un perro». La alegoría de Ezequiel sobre Jerusalén invierte la convención: ella da paga en vez de recibirla, haciéndola peor que una ramera común (Ez 16:31-34, 41). Isaías y Miqueas extienden la metáfora a las ganancias comerciales de naciones idólatras (Is 23:17-18; Mi 1:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85074, 'spa', 'Lugar, sitio', 'Designa un lugar o sitio físico, funcionando como sustantivo arameo estándar. En Esdras se refiere sistemáticamente al emplazamiento del templo: ''edifíquese la casa de Dios en su lugar'' (Esd 5:15; 6:7). El español lugar y el inglés ''place'' coinciden de manera uniforme en las cinco ocurrencias. El cognado siríaco atar y el uso nabateo y palmireno confirman un sustantivo espacial arameo común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85076, 'spa', 'Después de, tras', 'Funciona como preposición temporal que significa ''después de'' o ''tras'', derivada del sustantivo locativo mediante el modismo ba-atar (''en la huella de''). Daniel 2:39 emplea la forma con sufijo u-vathrakh (''y después de ti'') para introducir el reino siguiente, mientras que Daniel 7:6-7 usa ba-atar denah (''después de esto'') para la sucesión apocalíptica. El español después de y el francés après confirman la lectura puramente temporal.');